import{_ as i,o as s,c as l,a0 as e}from"./chunks/framework.CShDTZbC.js";const c=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md"}'),t={name:"zh-CN/guide/faq.md"};function n(h,a,o,r,p,d){return s(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="通用问题" tabindex="-1">通用问题 <a class="header-anchor" href="#通用问题" aria-label="Permalink to &quot;通用问题&quot;">​</a></h2><h3 id="什么是-airlinesim-autobuy" tabindex="-1">什么是 AirlineSim Autobuy？ <a class="header-anchor" href="#什么是-airlinesim-autobuy" aria-label="Permalink to &quot;什么是 AirlineSim Autobuy？&quot;">​</a></h3><p>AirlineSim Autobuy 是一个 Go 语言编写的自动化工具有可以持续监控 AirlineSim 游戏的二手飞机市场，根据用户自定义规则自动购买符合条件的飞机。它提供 Web 管理界面用于配置和监控。</p><h3 id="这个工具是否违反游戏规则" tabindex="-1">这个工具是否违反游戏规则？ <a class="header-anchor" href="#这个工具是否违反游戏规则" aria-label="Permalink to &quot;这个工具是否违反游戏规则？&quot;">​</a></h3><p>本工具仅用于个人学习和辅助游戏。使用者需自行承担使用自动化工具的风险。建议合理设置轮询间隔，避免对游戏服务器造成过大压力。</p><h3 id="支持哪些平台" tabindex="-1">支持哪些平台？ <a class="header-anchor" href="#支持哪些平台" aria-label="Permalink to &quot;支持哪些平台？&quot;">​</a></h3><p>程序使用 Go 语言编写，支持 Windows、Linux 和 macOS 三大平台。前端界面使用 Vue 3 构建，内嵌在 Go 二进制文件中，无需额外依赖。</p><h3 id="是否需要付费" tabindex="-1">是否需要付费？ <a class="header-anchor" href="#是否需要付费" aria-label="Permalink to &quot;是否需要付费？&quot;">​</a></h3><p>AirlineSim Autobuy 是开源项目，基于 MIT 许可证发布，完全免费使用。</p><h2 id="配置问题" tabindex="-1">配置问题 <a class="header-anchor" href="#配置问题" aria-label="Permalink to &quot;配置问题&quot;">​</a></h2><h3 id="如何配置多个服务器" tabindex="-1">如何配置多个服务器？ <a class="header-anchor" href="#如何配置多个服务器" aria-label="Permalink to &quot;如何配置多个服务器？&quot;">​</a></h3><p>在 <code>configs/config.yaml</code> 中使用 <code>servers</code> 数组配置多个服务器：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">free1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://free1.airlinesim.aero</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">free2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://free2.airlinesim.aero</span></span></code></pre></div><p>然后通过规则的 <code>server_id</code> 字段指定规则应用在哪个服务器上。</p><h3 id="如何配置多个账户" tabindex="-1">如何配置多个账户？ <a class="header-anchor" href="#如何配置多个账户" aria-label="Permalink to &quot;如何配置多个账户？&quot;">​</a></h3><p>使用 <code>auths</code> 数组配置多个认证账户：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;account1@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass1&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    session_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session1.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;account2@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass2&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    session_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session2.json</span></span></code></pre></div><p>每条规则可以通过 <code>auth_id</code> 指定使用哪个账户。</p><h3 id="配置文件的密码是明文存储的吗" tabindex="-1">配置文件的密码是明文存储的吗？ <a class="header-anchor" href="#配置文件的密码是明文存储的吗" aria-label="Permalink to &quot;配置文件的密码是明文存储的吗？&quot;">​</a></h3><p>是的，当前配置文件的密码以明文形式存储在 YAML 文件中。建议：</p><ul><li>限制配置文件的访问权限（<code>chmod 600 config.yaml</code>）</li><li>不要在版本控制中提交包含真实密码的配置文件</li><li>后续版本可能会支持环境变量或加密存储</li></ul><h3 id="修改配置文件后需要重启吗" tabindex="-1">修改配置文件后需要重启吗？ <a class="header-anchor" href="#修改配置文件后需要重启吗" aria-label="Permalink to &quot;修改配置文件后需要重启吗？&quot;">​</a></h3><p>不需要。程序内置了配置文件监控器，每 5 秒检查文件修改时间。检测到变化后会自动重新加载配置和规则。但修改服务器或认证信息后建议重启程序以确保完全生效。</p><h2 id="技术问题" tabindex="-1">技术问题 <a class="header-anchor" href="#技术问题" aria-label="Permalink to &quot;技术问题&quot;">​</a></h2><h3 id="程序启动后没有输出" tabindex="-1">程序启动后没有输出？ <a class="header-anchor" href="#程序启动后没有输出" aria-label="Permalink to &quot;程序启动后没有输出？&quot;">​</a></h3><p>检查以下可能的原因：</p><ol><li>配置文件路径是否正确（默认 <code>configs/config.yaml</code>）</li><li>配置文件格式是否正确（YAML 缩进错误）</li><li>网络连接是否正常（能否访问 <code>airlinesim.aero</code>）</li><li>账户信息是否正确</li></ol><h3 id="登录失败怎么办" tabindex="-1">登录失败怎么办？ <a class="header-anchor" href="#登录失败怎么办" aria-label="Permalink to &quot;登录失败怎么办？&quot;">​</a></h3><p>登录失败的可能原因：</p><ol><li>用户名或密码错误——检查配置文件中的凭据</li><li>网络问题——确保能够访问 <code>sar.simulogics.games</code></li><li>账户被锁定——尝试在浏览器中手动登录</li><li>API 变更——如果游戏更新了认证 API，程序可能需要更新</li></ol><h3 id="web-界面无法访问" tabindex="-1">Web 界面无法访问？ <a class="header-anchor" href="#web-界面无法访问" aria-label="Permalink to &quot;Web 界面无法访问？&quot;">​</a></h3><ol><li>确认程序正在运行</li><li>检查 WebUI 配置是否正确：<div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9090</span></span></code></pre></div></li><li>检查防火墙是否开放了对应端口</li><li>如果使用云服务器，检查安全组规则</li><li>尝试访问 <code>http://127.0.0.1:9090</code> 排除网络问题</li></ol><h3 id="如何查看运行日志" tabindex="-1">如何查看运行日志？ <a class="header-anchor" href="#如何查看运行日志" aria-label="Permalink to &quot;如何查看运行日志？&quot;">​</a></h3><ul><li><strong>控制台</strong>：默认在控制台输出结构化日志</li><li><strong>systemd</strong>：<code>journalctl -u airlinesim-autobuy -f</code></li><li><strong>Docker</strong>：<code>docker logs -f airlinesim-autobuy</code></li><li><strong>Web 界面</strong>：日志页面提供实时事件查看</li></ul><h3 id="如何修改日志级别" tabindex="-1">如何修改日志级别？ <a class="header-anchor" href="#如何修改日志级别" aria-label="Permalink to &quot;如何修改日志级别？&quot;">​</a></h3><p>程序启动时默认使用 <code>Info</code> 级别。要查看更详细的日志，可以在 <code>main.go</code> 中修改日志级别：</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">slog.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetDefault</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(slog.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">New</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(slog.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NewTextHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(os.Stdout, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">slog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HandlerOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Level: slog.LevelDebug,  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 改为 Debug 级别</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})))</span></span></code></pre></div><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h2><h3 id="规则匹配但未购买" tabindex="-1">规则匹配但未购买 <a class="header-anchor" href="#规则匹配但未购买" aria-label="Permalink to &quot;规则匹配但未购买&quot;">​</a></h3><p>可能的原因：</p><ol><li>规则的 <code>auto_buy</code> 设置为 <code>false</code>——将 <code>auto_buy</code> 改为 <code>true</code></li><li>评分计算为 0——检查匹配条件是否过于严格</li><li>余额不足——检查 <code>min_balance</code> 设置</li><li>购买操作失败——查看日志中的具体错误信息</li></ol><h3 id="遇到-url-validation-failed-错误" tabindex="-1">遇到 &quot;URL validation failed&quot; 错误 <a class="header-anchor" href="#遇到-url-validation-failed-错误" aria-label="Permalink to &quot;遇到 &quot;URL validation failed&quot; 错误&quot;">​</a></h3><p>这是安全机制在阻止请求。程序只允许连接到以下域名的服务器：</p><ul><li><code>airlinesim.aero</code> 及其子域名</li><li><code>sar.simulogics.games</code></li><li><code>simulogics.games</code></li></ul><p>如果出现此错误，请检查 <code>base_url</code> 配置是否正确。</p><h3 id="购买失败但没有错误信息" tabindex="-1">购买失败但没有错误信息 <a class="header-anchor" href="#购买失败但没有错误信息" aria-label="Permalink to &quot;购买失败但没有错误信息&quot;">​</a></h3><p>购买执行器会尝试：</p><ol><li>访问飞机详情页</li><li>提交购买表单或出价</li><li>检查响应状态码</li></ol><p>如果购买失败，检查：</p><ul><li>会话是否有效（可能已过期）</li><li>飞机是否已被其他人购买</li><li>账户余额是否充足</li><li>竞拍出价是否低于当前最高价</li></ul><h3 id="程序崩溃或-panic" tabindex="-1">程序崩溃或 panic <a class="header-anchor" href="#程序崩溃或-panic" aria-label="Permalink to &quot;程序崩溃或 panic&quot;">​</a></h3><p>如果遇到程序崩溃，请：</p><ol><li>查看完整的错误堆栈信息</li><li>检查配置文件是否有语法错误</li><li>确认网络连接稳定</li><li>在 GitHub 提交 Issue 时附上完整的错误日志和配置（注意隐藏密码）</li></ol><h3 id="如何重置会话" tabindex="-1">如何重置会话？ <a class="header-anchor" href="#如何重置会话" aria-label="Permalink to &quot;如何重置会话？&quot;">​</a></h3><p>删除会话文件（默认为 <code>session.json</code>），程序会在下次运行时自动重新登录。</p><h3 id="如何恢复默认配置" tabindex="-1">如何恢复默认配置？ <a class="header-anchor" href="#如何恢复默认配置" aria-label="Permalink to &quot;如何恢复默认配置？&quot;">​</a></h3><p>删除 <code>configs/config.yaml</code> 文件，程序会在下次启动时自动生成包含默认配置的新文件。</p><h3 id="如何报告问题或提出功能建议" tabindex="-1">如何报告问题或提出功能建议？ <a class="header-anchor" href="#如何报告问题或提出功能建议" aria-label="Permalink to &quot;如何报告问题或提出功能建议？&quot;">​</a></h3><p>请在 GitHub 仓库提交 Issue：</p><ul><li>问题报告：<a href="https://github.com/Maicarons/airlinesim-autobuy/issues" target="_blank" rel="noreferrer">https://github.com/Maicarons/airlinesim-autobuy/issues</a></li><li>请附上：程序版本、操作系统、错误日志、配置文件（隐藏密码）</li></ul><h2 id="其他问题" tabindex="-1">其他问题 <a class="header-anchor" href="#其他问题" aria-label="Permalink to &quot;其他问题&quot;">​</a></h2><h3 id="程序会占用多少系统资源" tabindex="-1">程序会占用多少系统资源？ <a class="header-anchor" href="#程序会占用多少系统资源" aria-label="Permalink to &quot;程序会占用多少系统资源？&quot;">​</a></h3><p>程序非常轻量：</p><ul><li><strong>CPU</strong>：仅在轮询时短暂使用，大部分时间空闲</li><li><strong>内存</strong>：通常占用 10-30 MB</li><li><strong>磁盘</strong>：二进制文件约 12 MB，配置文件约 1 KB</li><li><strong>网络</strong>：每次轮询发送 1-2 个 HTTP 请求</li></ul><h3 id="可以同时监控多少个服务器" tabindex="-1">可以同时监控多少个服务器？ <a class="header-anchor" href="#可以同时监控多少个服务器" aria-label="Permalink to &quot;可以同时监控多少个服务器？&quot;">​</a></h3><p>理论上没有限制，但建议不要超过 5-10 个服务器，以免对游戏服务器造成过大压力。每个服务器会在独立的 goroutine 中运行。</p><h3 id="程序会一直运行吗" tabindex="-1">程序会一直运行吗？ <a class="header-anchor" href="#程序会一直运行吗" aria-label="Permalink to &quot;程序会一直运行吗？&quot;">​</a></h3><p>程序会持续运行直到收到中断信号（SIGINT/SIGTERM）或手动停止。可以通过 Web 界面的&quot;启动/停止&quot;按钮控制引擎的运行状态，但即使引擎停止，Web 界面本身仍然可用。</p>`,69)])])}const u=i(t,[["render",n]]);export{c as __pageData,u as default};
